<template><el-card><template #header><div class="header"><strong>系统设置</strong><el-button v-if="auth.hasPermission('iam:setting:write')" type="primary" @click="open()">新增设置</el-button></div></template><el-table :data="items"><el-table-column prop="key" label="设置键"/><el-table-column prop="valueJson" label="JSON值" min-width="260"/><el-table-column prop="version" label="版本"/><el-table-column label="操作"><template #default="s"><el-button v-if="auth.hasPermission('iam:setting:write')" link type="primary" @click="open(s.row)">编辑</el-button></template></el-table-column></el-table></el-card><el-dialog v-model="dialog" title="系统设置"><el-form label-width="90px"><el-form-item label="设置键"><el-input v-model="form.key" :disabled="!!editingKey"/></el-form-item><el-form-item label="JSON值"><el-input v-model="form.valueJson" type="textarea" :rows="6"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></template>
<script setup lang="ts">
import { onMounted,reactive,ref } from 'vue';import { ElMessage } from 'element-plus';import { apiClient } from '@/api';import { useAuthStore } from '@/stores';import type { SettingRecord } from '@/types/management'
const auth=useAuthStore();const items=ref<SettingRecord[]>([]);const dialog=ref(false);const editingKey=ref('');const form=reactive({key:'',valueJson:'{}',version:0});async function load(){items.value=(await apiClient.get('/management/tenant/settings')) as SettingRecord[]}function open(row?:SettingRecord){editingKey.value=row?.key||'';Object.assign(form,row||{key:'',valueJson:'{}',version:0});dialog.value=true}async function save(){JSON.parse(form.valueJson);await apiClient.put(`/management/tenant/settings/${encodeURIComponent(form.key)}`,{valueJson:form.valueJson,version:form.version});ElMessage.success('保存成功');dialog.value=false;await load()}onMounted(()=>{void load()})
</script><style scoped>.header{display:flex;justify-content:space-between;align-items:center}</style>
